-- 53 Village Square: walks the crowd's legs. Each villager is a
-- `sorting_group` riding a path (`path_follow`); this turns each to face the
-- way it is going and swings its arms and legs by how far it went.
-- Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/53-village-square.scene"
local COUNT = 16
local captions = true
local walking = true
local folk = {}
local status

function init(entity)
    for i = 1, COUNT do
        local n = "V" .. i
        local root = Entity.find_by_name(n)
        if root then
            local x, y = Transform.get_position(root)
            folk[#folk + 1] = {
                root = root, x = x, y = y, face = 1, phase = i * 1.3,
                arm_f = Entity.find_by_name(n .. "ArmF"), arm_b = Entity.find_by_name(n .. "ArmB"),
                leg_f = Entity.find_by_name(n .. "LegF"), leg_b = Entity.find_by_name(n .. "LegB"),
            }
        end
    end
    status = Entity.find_by_name("Status")
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("Space") then
        walking = not walking
        for _, f in ipairs(folk) do PathFollow.set(f.root, "playing", walking) end
    end
    for _, f in ipairs(folk) do
        local x, y = Transform.get_position(f.root)
        local dx, dy = x - f.x, y - f.y
        f.x, f.y = x, y
        if math.abs(dx) > 0.05 then
            local face = dx > 0 and 1 or -1
            if face ~= f.face then
                f.face = face
                Transform.set_scale(f.root, face, 1)
            end
        end
        local step = math.sqrt(dx * dx + dy * dy)
        f.phase = f.phase + step * 0.09
        local swing = math.sin(f.phase) * math.min(1, step * 2)
        if f.leg_f then Transform.set_rotation(f.leg_f, 0.5 * swing) end
        if f.leg_b then Transform.set_rotation(f.leg_b, -0.5 * swing) end
        if f.arm_f then Transform.set_rotation(f.arm_f, -0.45 * swing) end
        if f.arm_b then Transform.set_rotation(f.arm_b, 0.45 * swing) end
    end
    if status then
        UI.set_text(status, #folk .. " villagers, each a sorting group of up to eight parts"
            .. (walking and "" or "   (paused)"))
    end
end
